// Junta los datos del formulario con la cualificacion del modelo.
const salida = [];
for (const item of $input.all()) {
  const body = $('Nuevo lead').first().json.body || {};
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { encaje: 'medio', urgencia: 'media', resumen: '', preguntas: [], motivo: 'cualificacion no parseable: ' + bruto.slice(0, 150), borrador: '' };
  }
  salida.push({
    json: {
      id: $execution.id,
      fecha_entrada: new Date().toISOString(),
      origen: 'formulario',
      nombre: body.nombre || '',
      email: body.email || '',
      empresa: body.empresa || '',
      peticion: String(body.peticion || '').slice(0, 1000),
      consentimiento: 'true',
      consentimiento_texto: 'Casilla del formulario web marcada el ' + new Date().toISOString(),
      encaje: datos.encaje ?? 'medio',
      urgencia: datos.urgencia ?? 'media',
      resumen: datos.resumen ?? '',
      preguntas: JSON.stringify(datos.preguntas ?? []),
      motivo: datos.motivo ?? '',
      borrador: datos.borrador ?? '',
      estado: 'cualificado',
      proximo_contacto: new Date().toISOString().slice(0, 10),
    },
  });
}
return salida;

