// Filtra los leads activos cuyo proximo_contacto es hoy o ya vencio,
// y prepara el resumen del repaso matinal.
const hoy = new Date().toISOString().slice(0, 10);
const activos = ['cualificado', 'contactado', 'en_conversacion', 'propuesta_enviada'];
const pendientes = [];
const sinFecha = [];
for (const item of $input.all()) {
  const l = item.json;
  if (!activos.includes(String(l.estado || ''))) continue;
  const fecha = String(l.proximo_contacto || '').slice(0, 10);
  if (!fecha) {
    sinFecha.push(l.nombre || l.email || l.id);
  } else if (fecha <= hoy) {
    pendientes.push('- ' + (l.nombre || l.email) + ' (' + l.estado + ', tocaba el ' + fecha + '): ' + String(l.resumen || '').slice(0, 80));
  }
}
let texto = 'Repaso comercial de hoy\n\n';
texto += pendientes.length
  ? 'Toca contactar (' + pendientes.length + '):\n' + pendientes.join('\n')
  : 'Hoy no toca ningun seguimiento.';
if (sinFecha.length) {
  texto += '\n\nOJO, leads activos SIN fecha de proximo contacto (se estan muriendo en silencio): ' + sinFecha.join(', ');
}
return [{ json: { texto, pendientes: pendientes.length, sin_fecha: sinFecha.length } }];
